-- Generated from verified source content. No demo accounts/results. Apply after 001 schema.
begin;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('welcome-90','course','Welcome-курс для команды: Стань частью бара «90-е»',null,'{"id":"welcome-90","title":"Welcome-курс для команды: Стань частью бара «90-е»","description":"Знакомство с концепцией, гостями, командой и первым рабочим днём. Перенесено из вашего ServiceGuru.","restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"Введение: Добро пожаловать в машину времени! 🚀🎶","text":"Привет, новобранец в мире 90-х! 👋\n\nТы когда-нибудь задумывался, каково это — не просто работать в баре, а запускать машину времени? ⏰✨ Здесь, в «Девяностые», мы делаем именно это. Каждый вечер мы отправляем наших гостей — и себя — в самое беззаботное путешествие: назад, в драйв и энергетику юности. 💃🕺\n\nНаша сеть баров создана, чтобы подарить людям не просто место для встреч, а живую ностальгию 🕰️❤️, место силы, где играют хиты 🎤🎧, поют в караоке до хрипоты 🎶🗣️ и знакомятся с историей через атмосферу.\n\nТы здесь не просто новый сотрудник. Ты — создатель настроения ✨\n\nТвоя улыбка 😊 — это первый аккорд вечера для гостя. Твоя энергия ⚡ — топливо для нашей дискотеки. Твоё умение почувствовать момент 🌟 — то, что превращает обычный выходной в незабываемую историю, которую захочется повторить.\n\nМы не просто подаём коктейли и закуски 🍹🍟. Мы создаём эмоции. 💛 Мы дарим тот самый «Улёт!» 🔥, от которого светятся глаза. И всё это теперь и в твоих руках.\n\nМы рады видеть тебя в команде сети баров «Девяностые»! Наши двери открыты в Химках, Мытищах и Пушкино. Единый номер для бронирования: +7 (495) 374-88-55.\n\nС верой в нашу общую драйвовую историю,\n\nКоманда «Девяностые». 🎤🙌","images":["assets/welcome/lesson-1-0.jpg"],"id":"122072"},{"title":"Наша ДНК — Чем мы дышим 🧬✨","text":"Наша концепция: 4 в 1 и точка возврата. 🔢🎯\n\nМы — не просто бар. Мы — формат «4 в 1»: дискотека 🪩, караоке 🎤, бар 🍸 и ресторан 🍽️ в одном флаконе. Но наша суперсила — атмосфера 90-х и 00-х 📼📟. Мы бережно воссоздаём её через детали: от хитов 90-х 🎶 и приставок Dendy 🎮 до меню в стиле молодёжных журналов 📰✨\n\nНаши столпы, на которых держится вся вечеринка: 🏛️🎉\n\n1. Ностальгия — наше топливо. ⏳❤️ Мы не играем в ретро — мы живём в нём. Каждая мелодия 🎵, каждый элемент интерьера (кассеты 📼, плакаты 🖼️, малиновые пиджаки 🧥, олимпийки) — это портал 🚪🌀. Твоя задача — помочь гостю в него шагнуть.\n\n2. Драйв — наш главный продукт. ⚡🔥 Мы продаём не столики, а ощущение праздника 🎊. Будь то концерт звезды 90-х 🌟, караоке-баттл 🎤⚔️ или просто танцы до утра 💃🕺 — энергия должна быть на максимуме. Всегда. 📈\n\n3. Гостеприимство без пафоса. 😊🙌 У нас демократично и по-домашнему 🏠. Наш гость — друг, который пришёл оторваться 🎢. Общайся соответственно: легко, с улыбкой 😁, с лёгкой шуткой 😜. Но помни про уважение и профессиональный сервис 🤝✨\n\n4. Качество в деталях. 🔍💎 Беспроигрышные хиты кухни по единой цене 390 ₽ 🍔🍟, фирменные коктейли с дерзкими названиями, профессиональный звук 🎚️🔊 — за этим мы следим строго. Потому что гости приходят за целостным опытом 🎯\n\nНаши ценности: 💎\n\n· Улётность: 🚀✨ Делай так, чтобы гости уходили с мыслью «Это было огнище!» 🔥\n\n· Искренность: 💛🫶 Улыбайся и шути потому, что тебе нравится здесь быть, а не «потому что надо» ❌😬\n\n· Командность: 👥🤝 Мы — экипаж машины времени 🚂⏰. Без слаженной работы далеко не уедем 🚫💨","images":["assets/welcome/lesson-2-0.jpg"],"id":"122073"},{"title":"Наши гости — ради кого крутится эта кассета 📼🎶👥","text":"Кто они? 🤔\n\n· Поколение 35-45 лет (Наши главные путешественники) 🧭❤️:\n\n🔹Они пришли за ностальгией 🕰️. Запах «Первым делом — самолёты» ✈️, первая любовь под хиты 90-х 💕… Они хотят снова почувствовать тот драйв ⚡. Они ценят тёплое общение ☕🗣️ и знают толк в хорошем вечере 🌙✨.\n\n🔹Твой лайфхак: 💡 Упомяни в разговоре что-то из той эпохи («Как тот самый сингл из MTV!» 📺🎤) — и ты мгновенно найдёшь общий язык 🤝😉.\n\n· Молодёжь (Любители ретро-стиля) 🧢📟:\n\n🔹Для них 90-е — модный тренд 🔥👖. Они приходят за энергией ⚡, тусовкой 🎉, за крутыми фото в наших фотозонах 📸✨ («90-е снова в тренде!»).\n\n🔹Твой лайфхак: 💡 Будь на одной волне 🌊, заряжай их энергией 🔋, предложи самый популярный в Instagram 📱🍹 коктейль.\n\n· Именинники и компании на праздник 🎂🥳🎈:\n\n🔹Выбирают нас для дней рождений и банкетов 🎊🍾. Для них важна предпраздничная суета 🏃‍♂️🎁, внимание к деталям 🔍💝 и чтобы всё прошло на ура 🚀🎯.\n\n🔹Твой лайфхак: 💡 Поздравь от всей команды! 🥂👏 Небольшой знак внимания создаст море лояльности 🌊💙.\n\nКак мы с ними говорим? 🗣️💬\n\nНаш голос — друг, который знает все хиты и не боится их петь 🎤🎶😎. Современный, ироничный, полный энергии ⚡✨. Мы не говорим «у нас караоке», мы говорим «готов сорвать зал?» 🔥🎤💥. Чувствуешь разницу? 😏👌\n\nЗабронировать стол можно по единому номеру +7 (495) 374-88-55. Мы ждём гостей в Химках, Мытищах и Пушкино.","images":["assets/welcome/lesson-3-0.jpg"],"id":"122074"},{"title":"Наше пространство — твоя сцена 🏠🎤🎬","text":"Видео экскурсия по бару из Химок","images":[],"video":"assets/welcome/khimki-tour.mp4","id":"121198"},{"title":"Команда — твой экипаж 👥🤝🚂","text":"Кто есть кто: 🧑‍🤝‍🧑\n\n Управляющий / Менеджер: 👨‍✈️🧢 Капитан корабля. Решает все оперативные вопросы ⚓📋\n\n· Хостес: 🚪✨ Первое лицо. Создаёт настроение с первых секунд ⏱️💫\n\n· Официант: 🍽️🏃‍♂️ Проводники удовольствия. Знают всё о меню и коктейлях 📋🍹\n\n· Повар: 👨‍🍳✨ Волшебник вкуса. Превращает продукты в ностальгические хиты 🍔🎶\n\n· Бармен: 🍸🎭 Создатель настроения в жидком виде. Его коктейли — часть шоу 🤹‍♂️🥂\n\n· Работник зала / Мойщик посуды: 🧹🦸‍♂️ Герои невидимого фронта. Без них сцена быстро превратится в хаос 💪⚙️\n\nТвой безупречный вид: Smart Casual с искрой ✨👔\n\nТы — часть эстетики 90-х, но в современной упаковке 🎁📼\n\n· Базовый стандарт: ✅ Аккуратный, стильный smart casual 👌. Чистая обувь 👞✨, чистая кожа (желательно наличие штукатурки) 🧴, уложенные волосы 💇‍♂️, ухоженные ногти 💅\n\n· Можно: 👍 Свою стильную одежду в духе времени 🕶️, джинсовки 👖, яркие цвета 🌈, модные аксессуары 🕶️🧣\n\n· Нельзя: ❌ Спортивные костюмы 👕, пляжную обувь 🩴, неопрятность 🧟. Помни, у нас строгий фейс-контроль и для гостей — будь для них примером 🚫👮‍♂️\n\n· Почему это важно? ❓ Ты — живой элемент атмосферы 🎭. Твой вид должен говорить: «Я часть этой крутой эпохи» 💬👌📟✨","images":["assets/welcome/lesson-5-0.jpg"],"id":"122076"},{"title":"Твой первый день — Поехали! 🚀🎉","text":"Чек-лист перед стартом: ✅📋\n\n· Настроение на драйв ⚡✓\n\n· Удобная чистая одежда в стиле smart casual 👕✨✓\n\n· Знание главных хитов 90-х 🎶✓\n\n· Готовность улыбаться и творить 😊💫✓\n\nПримерный план дня: 📅🗓️\n\n· Встреча с менеджером. Знакомство, документы 🤝📄\n\n· Экскурсия по бар-машине времени с наставником 🚂⏰👣\n\n· Знакомство с командой и дегустация хитов меню (все позиции по 390₽ 🌭🍹)\n\n· Стажировка с наставником на своей позиции 👨‍🏫💼\n\nВажно! ❗⚠️\n\n· Не бойся задавать вопросы. 🙋‍♂️🙋‍♀️ Менеджер, бармен, официант — все здесь, чтобы помочь тебе влиться 💪🤗","images":["assets/welcome/lesson-6-0.jpg"],"id":"122077"},{"title":"Завершение: Время начинать вечеринку! 🎉🚀🎶","text":"Поздравляю! 🎊👏 Ты только что загрузил в себя всю прошивку «Девяностые» 📲💾✨\n\nТеперь ты не просто новичок. Ты — хранитель портала. 🗝️🚪 Ты знаешь, ради чего мы здесь: чтобы каждый вечер дарить людям побег из рутины 🏃‍♂️💨, море эмоций 🌊💖 и воспоминания, ради которых хочется возвращаться 📸💭\n\nПомни: здесь каждый твой день — это шанс стать круче 📈😎, научиться чувствовать людей ❤️🤝, создавать праздник своими руками 🎊✨. Мы растём и отрываемся вместе! 🌱🚀\n\nДобро пожаловать в самую драйвовую команду 👋🎉. Готовь голосовые связки 🎤, удобную обувь 👟 и отличное настроение 😊✨\n\nЖдём тебя на точке в Химках, Мытищах или Пушкино 📍👀. Пора запускать двигатели! 🚀🔥🎶\n\nКоманда «Девяностые».","images":["assets/welcome/lesson-7-0.jpg"],"id":"122078"},{"title":"Руководство компании","text":"Руководство компании — исходные слайды из ServiceGuru.","images":["assets/welcome/lesson-8-0.jpg","assets/welcome/lesson-8-1.jpg","assets/welcome/lesson-8-2.jpg","assets/welcome/lesson-8-3.jpg","assets/welcome/lesson-8-4.jpg","assets/welcome/lesson-8-5.jpg","assets/welcome/lesson-8-6.jpg","assets/welcome/lesson-8-7.jpg","assets/welcome/lesson-8-8.jpg","assets/welcome/lesson-8-9.jpg","assets/welcome/lesson-8-10.jpg"],"id":"123016"}],"outline":[{"type":"lesson","lessonIndex":0,"title":"Введение: Добро пожаловать в машину времени! 🚀🎶"},{"type":"lesson","lessonIndex":1,"title":"Наша ДНК — Чем мы дышим 🧬✨"},{"type":"lesson","lessonIndex":2,"title":"Наши гости — ради кого крутится эта кассета 📼🎶👥"},{"type":"lesson","lessonIndex":3,"title":"Наше пространство — твоя сцена 🏠🎤🎬"},{"type":"lesson","lessonIndex":4,"title":"Команда — твой экипаж 👥🤝🚂"},{"type":"lesson","lessonIndex":5,"title":"Твой первый день — Поехали! 🚀🎉"},{"type":"test","id":"104460","title":"Проверка знаний 📝🧠✅"},{"type":"lesson","lessonIndex":6,"title":"Завершение: Время начинать вечеринку! 🎉🚀🎶"},{"type":"lesson","lessonIndex":7,"title":"Руководство компании"}],"testIds":["104460"]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('waiter-standards','course','Стандарты работы официанта',null,'{"id":"waiter-standards","title":"Стандарты работы официанта","description":"Правила работы, открытие смены, обслуживание гостей и чек-бэк. Исходные материалы вашей команды «90-е».","brand":"90-е","restaurantIds":["pushkino","khimki","mytishchi"],"departments":["Зал"],"positions":["Официант","Администратор","Хостес"],"questions":[],"pass":80,"lessons":[{"title":"Урок 1. Правила работы официанта","text":"Кто такой официант?\n\nТы стал частью реально клёвой команды официантов \"Бара 90-е\". Это не просто работа – это тусовка, где ты не только разносишь заказы, но и создаёшь атмосферу 90-х! Гость должен чувствовать себя как на вечеринке у старых друзей, и ты – главный ведущий этого движа.\n\nДелай так, чтобы гость запомнил этот вечер, захотел вернуться и притащил с собой друзей! Для этого важно знать основные правила, выглядеть как надо и владеть всеми нужными навыками.\n\nКакие правила?\n\nПриход на работу 🏃‍♂️\n\nНа смену приходим за час до старта: ВС - ЧТ к 17:00, ПТ и СБ к 16:30. Зал должен быть готов к работе в 17:45.\nОпаздываешь? Проблема! Заранее предупреди менеджера, если не успеваешь. Опоздания портят атмосферу и работу всей команды. Здесь важен командный дух, поэтому подводить своих не вариант.\nЕсли заранее нашел себе замену – молодец, но все равно предупреди.\n\nПерекуры 🚬\n\nКурить в рабочее время – так себе идея. Можно только если зал без гостей и каждая позиция прикрыта коллегами, за исключением времени 23:00 - 03:00\nНе ходи курить группой, ты же не на перемене в школе!\nПосле перекура – жвачка или спрей для свежести\n\nОбщение с гостями 🗣\n\nВсегда улыбаемся! Даже если день не задался – твоя улыбка делает атмосферу.\nИспользуем лёгкий сленг 90-х – так гости сразу понимают, что здесь их ждёт ностальгия\nЕсли что-то не знаешь, уточни у менеджера, а если это происходит в разговоре с Гостями - предупреди, что уточнишь и вернешься с ответом.\nДержим лицо в любой ситуации – даже если гость капризный, решаем всё с позитивом и юмором\n\nЭто еще не все правила, которые ты должен соблюдать. Чтобы изучить их, переходи в Библиотеку , там есть Правила сотрудника на смене\n\nКак должен выглядеть официант \"Бара 90-е\"?\n\nФизическая форма – Симпатяга\n\nЧистая кожа (желательно наличие штукатурки), уложенные волосы, ухоженные ногти\nСвежий аромат – без перегибов с резким парфюмом.\nСтильный прикид в духе 90-х: джинсовки, яркие цвета, модные аксессуары.\nФорма должна быть чистой и аккуратной. Если вид неопрятный – гость подумает, что и еда у нас такая же.\nФорма должна быть чистой и аккуратной. Если вид неопрятный – гость подумает, что и еда у нас такая же.\nДля нас официант – это:\nГлавный моторчик движа, без которого не будет улетной атмосферы.\nВеселый друг, которому не фиолетово, что происходит в зале – он понимает, что всё зависит от него.\nЧеловек, который сам тащится от заведения и заряжает этой любовью гостей. Они возвращаются снова и снова, потому что здесь кайф!\nДля наших гостей официант – это:\n\nЭмоции: Лучший друг\n\nСвой в доску, всегда на позитиве, улыбается и создаёт уютную атмосферу домашнего праздника.\n\nЛичностные качества: Радушный хозяин\n\nВнимательный – сразу видит, что нужно гостю, и приносит это моментально.\nЧестный – никаких мутных тем, репутация заведения на кону.\nДержит лицо – даже если устал или день не задался, гостю этого видеть не положено.\nНе сыплет негативом – бар должен быть местом кайфа, а не разборок.\nРазруливает конфликты ещё до того, как они завелись.\nОткрытый – сам заводит разговор, легко общается, помогает выбрать блюдо.\n\nПрофнавыки: Знает и умеет\n\nРазбирается в меню как настоящий профи: знает, что вкусное, как готовят, за сколько минут принесут.\nМастер подачи: напитки и блюда на столе всегда быстро, красиво и в правильном порядке.\nЧек закроет в два счёта, а стол поддержит в идеальной чистоте","images":["assets/waiter/lesson-1-0.jpg","assets/waiter/lesson-1-1.jpg","assets/waiter/lesson-1-2.jpg","assets/waiter/lesson-1-3.jpg","assets/waiter/lesson-1-4.jpg"],"id":"42956"},{"title":"Урок 2. Стандарты открытия смены","text":"Открытие зала\n\nЧек-лист – твой лучший инструмент, чтобы держать всё под контролем! Это список вещей, которые нельзя пропустить при открытии смены.\n\nМебель. Опустить стулья, выровнять мебель, почистить ее средством, протереть подножья столов и стульев \nСтолы. Протереть их чистой влажной тряпкой \nЗасервировать столы. Постановочная тарелка, столовые приборы (нож, вилка), хайбол, тейблтенты с актуальной информацией, салфетница, текстильная салфетка. Приборы ополаскиваем в кипятке либо брызгаем разведенным уксусом\nПроверить и заполнить расходники в стейшене, также в стейшенах всегда должна быть чистая вода в ведре для уборки столов\nПривести в порядок декор зала, протереть пыль \nРасставить таблички с надписями на барный стол \nВсё в порядке? Значит, ты готов к улётной смене! 🚀","images":["assets/waiter/lesson-2-0.jpg"],"id":"42957"},{"title":"Урок 3. Обслуживание гостей","text":"Как сделать так, чтобы гость вернулся? 🎤🔥\nЛистай шаги обслуживания и запоминай\n\nВрываемся с улыбкой! 😃\n\nЗаходим на позитиве – дарим гостю хорошее настроение с порога и представляемся!\nМеню подаём открытой рукой\nБонус: пока гость листает меню, предлагай что-нибудь освежающее – сразу +1 к продажам!\nВыясняем, чего душа хочет, помогаем выбрать блюда\nРаскачиваем эмоции – аппетитные описания блюд, от которых слюнки потекут.\nБонус: «Хотите крутой гарнир или эксклюзивный соус к этому?» – больше вкуса, больше кайфа, больше продаж!\nВремя приготовления – если задержка, сразу говорим реальное время, гость будет благодарен за честность.\nПовторяем заказ – чтобы не испортить впечатления от возможной ошибки!\nБлюда подаём открытой рукой, как профессионалы.\nВсё приносим синхронно – никто не ждёт, все довольны!\nПервыми – закуски, потом горячее, потом десерты – чистый ритм сервиса!\n«Ну как? Огонь? 🔥» – не просто спрашиваем, а реально чувствуем эмоции гостя!\nЕсли что-то не так – сразу решаем вопрос.\nГасим возможные конфликты ещё до их появления.\n\nПодробнее о чек бэке - в следующем уроке\n\nГость попросил счёт? Не стоим, несём моментально!\nБонус: «А у вас есть скидочная карта?» – вдруг гость забыл, а ты напомнишь\n«Наличные или карта, общий или раздельный?» – всё чётко, без лишних вопросов.\n«Спасибо, что заглянули, ждём снова!» – главное, чтобы звучало искренне.\nФинальный аккорд: Улыбка, кивок, возможно даже стильный жест рукой – гость должен уходить с ощущением, что его реально ждали!\nПересервируем стол за 2-3 минуты – новые гости уже на подходе!","images":["assets/waiter/lesson-3-0.jpg","assets/waiter/lesson-3-1.jpg","assets/waiter/lesson-3-2.jpg","assets/waiter/lesson-3-3.jpg","assets/waiter/lesson-3-4.jpg","assets/waiter/lesson-3-5.jpg","assets/waiter/lesson-3-6.jpg"],"id":"42959"},{"title":"Урок 4. Чек-бэк и его важность","text":"Для начала: что такое чек-бэк?\n\nCheck Back (чек-бэк) – это твой инструмент, чтобы понять, насколько гость доволен. Вкусно ли ему? Всё ли ок с качеством блюд и напитков? Не нужно ли ему что-то еще (салфетки, соус, пепельница)? А ещё чек-бэк – это твой шанс предотвратить конфликт на ранней стадии!\n\nКак его делать?\nПосле подачи блюд ждём немного времени, чтобы гость успел попробовать.\nПодходим, спрашиваем, как ему еда.\nЕсли гость недоволен – выясняем, в чём дело.\nЕсли проблема из-за качества блюда (неправильно приготовлено, остывшее и т.д.), сообщаем менеджеру.\nМенеджер решает, включать ли блюдо в счёт.\nВиды чек-бэка:\n\nТекущий – быстрый фидбэк\n\nЖдёшь 2-3 минуты после первой вилки еды.\nПодходишь, если гость заказал твою рекомендацию или новинку.\nВажно! Не перебиваем важную беседу, ждём удачного момента.\n\nПоэтапный – шаг за шагом\n\nСпрашиваем мнение, когда убираем тарелку.\nЕсли гость не доел – обязательно выясняем, почему.\nЕсли гость не в восторге от твоей рекомендации – не паримся: «Да, вкусы у всех разные, зато теперь я знаю, что советовать вам в следующий раз!»\n\nКонтрольный – закрепляем успех\n\nСпрашиваем о впечатлениях, когда гость просит счёт.\nОн ещё раз вспоминает, как классно провёл время.\nПроговаривая впечатления, фиксирует их в памяти, а значит, захочет вернуться!\n\nВажный момент!\n\nНе спрашиваем скучные «Всё ли в порядке?» или «Вам что-то не нравится?» – такие вопросы не цепляют. Подходи к гостю с искренним интересом!\n\nКакой чек-бэк использовать? ﻿﻿﻿﻿Решай сам, пробуй разные варианты и найди тот, который работает для тебя лучше всего! 🚀","images":["assets/waiter/lesson-4-0.jpg","assets/waiter/lesson-4-1.jpg"],"id":"42958"}],"outline":[{"type":"lesson","lessonIndex":0,"title":"Урок 1. Правила работы официанта"},{"type":"test","id":"92988","title":"Тест 1. Правила работы официанта"},{"type":"lesson","lessonIndex":1,"title":"Урок 2. Стандарты открытия смены"},{"type":"test","id":"92998","title":"Тест 2. Открытие смены"},{"type":"lesson","lessonIndex":2,"title":"Урок 3. Обслуживание гостей"},{"type":"test","id":"92995","title":"Тест 3. Обслуживание гостей"},{"type":"lesson","lessonIndex":3,"title":"Урок 4. Чек-бэк и его важность"},{"type":"test","id":"92993","title":"Тест 4. Чек бэк"}],"testIds":["92988","92998","92995","92993"]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
insert into public.academy_content(id,kind,title,course_id,payload,published,restaurant_id,department) values ('hostess-standards','course','Стандарты работы хостес',null,'{"id":"hostess-standards","title":"Стандарты работы хостес","shortTitle":"Стандарты хостес","coverLabel":"Первое<br>впечатление","description":"Встреча гостей, бронирование, рассадка, телефонный этикет и сложные ситуации.","kind":"course","brand":"90-е","departments":["Зал"],"positions":["Хостес","Администратор"],"restaurantIds":["pushkino","khimki","mytishchi"],"questions":[],"pass":80,"lessons":[{"title":"Кто такая хостес?","text":"Хостес — это ТА САМАЯ девушка, которая встретит гостя с улыбкой и предложит лучшую зону отдыха!\n\nЦели хостес:\n\n✅ Создать уютную атмосферу спокойствия и безопасности в нашем ресторане.\n\n✅ Найти индивидуальный подход к каждому гостю.\n\n✅ Подарить расслабленную атмосферу, гостеприимства и радушия. \n\nДолжностные обязанности:\n\n✔️ Начало рабочей смены в соответствии с графиком работы заведения (16:30-17:00).\n\n✔️ Поддержание чистоты рабочего места.\n\n✔️ Проверить и привести в порядок меню и барную шпаргалку (протереть, испорченные сфотографировать, отправить менеджеру/управляющему).\n\n✔️ Обработка заявок.\n\n✔️ Встреча гостя.\n\n✔️ Решение спорных или конфликтных ситуаций с гостем.\n\nНа рабочем месте всегда должны находиться в нужном количестве:\n\n1. Основное меню (15-20 шт.)\n\n2. Барная шпаргалка (15-20 шт.)\n\n3. Банкетное меню\n\n4. Вкладыши в основное\\барное меню\n\n5. Визитки\n\n6. Табель прихода/ухода (15 шт.)\n\n7. Тейбл Тент с условиями входных карт\n\n8. Анкета для соискателя (10 шт.)\n\n9. Правила поведения на смене (10 шт.)\n\n10. Договор о внесении предоплат (10 шт.)\n\n11. Договор на ДР (Пакетное Предложение - 10 шт.)\n\n12. Заполненная аптечка\n\n13. Кассеты “резерв” чистые, целые\n\n14. Папка для документации\n\n15. Папка с методичкой для Хостес\n\n16. Необходимая канцелярия (ножницы, клей, точилка, степлер, скотч, скобы, скрепки, резинки, стикеры, бумага А4, ручки, простые карандаши)\n\n17. Карандаши, раскраски, пазлы для детей\n\n18. “Сигналы” о первом визите гостя, менеджеру/официантам: тетрис, кубик Рубика, змейка","images":["assets/extra-courses/hostess-standards-0-0.jpg","assets/extra-courses/hostess-standards-0-1.jpg","assets/extra-courses/hostess-standards-0-2.jpg"],"links":[],"id":"101468"},{"title":"Внешний вид хостес","text":"✅ Внешний вид хостес должен соответствовать установленным стандартам.\n\n✅ Внешний вид хостес важен не только для создания хорошего первого впечатления, но и для поддержания общего имиджа. Гости часто оценивают качество обслуживания по внешнему виду персонала. Если хостес выглядит профессионально и ухоженно, это внушает доверие и создает положительное впечатление о заведении в целом.\n\nDress-code\n\n🟣 Дополни свой лук яркими тенями, причёской, красивым маникюром, аксессуарами а-ля 90-е!\n\n🟢 Приветствуется ультраяркий блестящий мейкап.\n\n👩 Причёски\n💅Маникюр\nСтиль — ты можешь быть разной!","images":["assets/extra-courses/hostess-standards-1-0.jpg","assets/extra-courses/hostess-standards-1-1.jpg","assets/extra-courses/hostess-standards-1-2.jpg","assets/extra-courses/hostess-standards-1-3.jpg","assets/extra-courses/hostess-standards-1-4.jpg"],"links":[],"id":"101469"},{"title":"Работа хостес на смене","text":"Перед началом смены:\n\n1️⃣ Проверить баланс мобильного телефона.\n\n2️⃣ Проверить Мессенджеры.\n\n3️⃣ Проверить брони на сегодняшнюю дату, проинформировать менеджера и официанта о банкетах.\n\n4️⃣ В 17:45 на собрании озвучить Арт-программу, актуальные акции и условия входа на данную дату.\n\nВо время рабочей смены:\nРабота с гостями\n\nПервая встреча с гостем закладывает основу для всего их визита. Приветливое и внимательное отношение хостес помогает создать положительное впечатление с самого начала. Гости ценят, когда их пожелания учитываются, и они чувствуют себя важными и желанными.\n\nВстреча гостя:\n\n﻿👋 Приветствуем гостя, устанавливаем зрительный контакт, улыбаемся. Улыбка является непременной частью в работе хостес\n\n🎀 Верхнюю одежду гостей (шуба, куртка, пиджак и т.д.) обязательно нужно сдать в гардероб. Всегда сначала вешают детскую, потом женскую и затем мужскую одежду. \n\n✅ Уточняем бронировал ли гость стол.\n\nЕСЛИ ДА - уточняем имя, номер телефона, количество персон и провожаем к столу, подаем меню по количеству человек и говорим: “хорошего вечера”. Уведомляем официанта о новой “посадке” (если гость впервые у нас выдаем “сигнал”).\nЕСЛИ НЕТ - уточняем имя, номер телефона, предпочтение по залам (основной, караоке).\n\n✅ В депозитные и праздничные дни: уточняем бронировал ли гость стол.\n\nЕСЛИ ДА - уточняем имя, номер телефона, кол-во персон, озвучиваем сумму депозита, согласно количеству гостей, озвучиваем сумму внесенной предоплаты и сумму ДОплаты, принимаем денежные средства, надеваем браслеты, провожаем за стол, желаем хорошего вечера.\nЕСЛИ НЕТ - уточняем имя, номер телефона, количество персон, предпочтения по залам (основной зал, барная стойка, караоке зал). Предлагаем свободные столы, озвучивая сумму депозита.\nЕсли к гостям, сидящим за столом, хотят присоединиться вновь пришедшие гости, необходимо пополнить депозит исходя из стоимости данного стола (в депозитный день). После того как хостес встретила гостя, проводила его за стол, вынесла меню, необходимую всю информацию передать сотрудникам зала - в чаты “депозиты”.\n\nПровожаем к столу:\n\n✔️ Провожая Гостя к столу хостес должна идти впереди Гостя, не теряя его из виду. Важно держать дистанцию, но и не уходить далеко, чтобы Гость не потерялся и не занялся поиском стола самостоятельно.\n\n✔️ Продолжай поддерживать разговор, можно рассказать о проводимых акциях, о специальных предложениях, планируемых мероприятиях.\n\n❌ Никогда не сажай Гостей за грязные столы.\n\nВажно не забыть попрощаться с каждым уходящим гостем.\n\nПри прощании, можно поинтересоваться, насколько им понравилось у нас, и пригласить их прийти снова, например:\n\n\"Я рада, что вам у нас понравилось. До свидания!\"\n\"До свидания, всего хорошего!\"\n\"Удачного дня!\"\n\"Ждем вас снова!\"\n\"Всего доброго!\"\n\nЕсли гости выразили похвалу кухне или обслуживанию, обязательно передайте эту похвалу соответствующему сотруднику.","images":["assets/extra-courses/hostess-standards-2-0.jpg","assets/extra-courses/hostess-standards-2-1.jpg","assets/extra-courses/hostess-standards-2-2.jpg","assets/extra-courses/hostess-standards-2-3.jpg"],"links":[],"id":"101470"},{"title":"Скрипт общения хостес \"Бара 90-е\"","text":"✅ Ключевые моменты, которые нужно озвучить :\nИмя гостя.\nДата и время.\nОтдыхали гости ранее в нашем баре?\nКакое мероприятие/ в каком формате гость хочет отметить событие?\nЗнаком ли гость с баром, акциями. Предлагаем Пакеты\nFC /DC 18 +, Сервисный сбор (от 6 человек)\nУсловия отдыха (если караоке, то условия исполнения песен)\nВарианты внесения оплаты\nПодтверждаем бронь\nСкрипты для встречи гостя:\n\n1. Добрый вечер(18:00-00:00) / Доброй ночи (00:00-06:00).\n\n2. Вы бронировали стол?\n\n3. Давайте проверим вашу бронь?\n\n4. Какое событие вы отмечаете?\n\n5. Вам стол на какое количество гостей?\n\n6. Если гость пришел один: “К Вам кто-нибудь присоединиться?\"\n\n❗ВАЖНО: Если Гость один, то единственной верной фразой является: \"На сколько персон Вам стол? К вам кто-то присоединиться?\"\n\n❌ НЕЛЬЗЯ употреблять фразу “Вы будете один?” \n\n✔️ Если гость бронировал стол:\nКак Вас зовут? Подскажите, пожалуйста последние 4 цифры Вашего номера.\nНашла Вашу бронь, оставьте, пожалуйста верхнюю одежду в гардеробе, и я Вас провожу за стол.\nВы отдыхаете на условиях депозита, необходимо внести остаток депозита в размере ……. руб. (После получения оплаты необходимо прописать депозит в чате Депозиты, чтобы официант видел депозит стола).\nХочу напомнить, что депозитом Вы можете оплатить барные напитки, еду, и кальян. Хорошего вечера!\n✖️ Если гость стол не бронировал:\nВы отдыхали у нас ранее, чтобы я Вас сориентировала по столам?\nХотели бы отдыхать в зоне караоке или танцпола?\nСтолы у нас бронируются по условиям депозита, депозитом Вы можете оплатить барные напитки, еду и кальян.\n\n \n\nХостес демонстрирует свободные столы, и озвучивает условия брони.\n\nКакая зона Вам больше понравилась?\nНеобходимо сразу внести сумму депозита.\n\nЗатем хостес размещает гостей и берет оплату.","images":["assets/extra-courses/hostess-standards-3-0.jpg"],"links":[],"id":"101617"},{"title":"Работа со сложными гостями","text":"Каждый гость уникален, и иногда вы можете столкнуться с недовольными или требовательными посетителями. Важно понимать, что такие ситуации требуют особого подхода и навыков. Цель хостес в таких ситуациях – разрешить конфликт так, чтобы гость ушел довольным и с положительным впечатлением о ресторане.\n\nОсновные принципы работы со сложными гостями\n\n➡️ Оставайтесь спокойными и вежливыми:\n\nНезависимо от того, насколько раздраженным или недовольным может быть гость, важно сохранять спокойствие и профессионализм. Ваше поведение задает тон всему взаимодействию.\n\n➡️ Внимательное слушание:\n\nПозвольте гостю высказать свои претензии или беспокойства без перебиваний. Внимательное слушание показывает, что вы уважаете его мнение и готовы помочь.\n\n➡️ Эмпатия и понимание:\n\nПостарайтесь понять чувства гостя и выразите сочувствие. Например, вы можете сказать: «Я понимаю, что вы расстроены, и мне очень жаль, что это произошло. Давайте посмотрим, как мы можем решить эту проблему»\n\n➡️ Быстрое реагирование:\n\nПостарайтесь как можно быстрее найти решение проблемы. Если вы не можете решить ситуацию самостоятельно, привлеките менеджера или другого ответственного сотрудника.\n\n➡️ Предложение решений:\n\nПредложите гостю несколько вариантов решения проблемы. Это может быть замена блюда, скидка или другой жест доброй воли. Важно, чтобы гость почувствовал, что его мнение ценно и что вы готовы сделать всё возможное для его удовлетворения.\n\nРешение спорных или конфликтных ситуаций с гостем\n\n1️⃣ Выслушиваем гостя, благодарим за обратную связь.\n\nДаже если мы понимаем, что Гость не прав, никогда не говорите ему об этом прямо. Дайте ему понять, что нам было крайне важно узнать именно его точку зрения по данному вопросу. Поблагодари его за то, что он нашел время рассказать нам о своих пожеланиях. Если Гости жалуются на что-то, обязательно покажи им, что мы искренне озабочены их проблемами. Никогда не спорьте с гостем! Передайте информацию менеджеру!\n\n2️⃣ Уточнить что именно не понравилось гостю, поинтересоваться, каким образом мы можем исправить данную ситуацию.\n\nЕсли ситуация несложная, получить информацию у менеджера к решению ситуации. В случае серьёзного конфликта, менеджер сам решает вопрос.\n\nСоветы\n\n✔️ Попадая в сложную ситуацию, необходимо сразу «поставить диагноз» - сможет ли хостес самостоятельно решить ситуацию или необходимо содействие руководителя. Это должно быть первым осмысленным действием на пути разрешения конфликта.\n\n✔️ Во время уточнения жалобы из всех механизмов сознания хостес должна работать только одна – память. Задача хостес слово в слово запомнить замечания и передать также руководителю. Необходимо помнить: здесь, как нигде, важны детали сказанного.\n\n✔️ Запрещено вступать в спор с гостем, пытаться что-либо доказать или опровергать его претензии.\n\n✔️ При выполнении продиктованных руководителем действий, не надо обсуждать, разбирать причины. Все эти вопросы хостес проанализирует потом. Сейчас важно быстро и четко выполнить конкретную задачу.\n\n✔️ Если гость желает выполнение действий, которые невозможно совершить, необходимо не разочаровывать гостя, мягко объяснить ему, что то, о чем он просит, невозможно. Взамен предложить что-нибудь другое, не менее интересное – это значит уметь убедить гостя.\n\n✔️ При конфликте спокойная и доброжелательная улыбка хостес, корректный и выдержанный тон невольно снимут эмоциональное напряжение гостя.","images":["assets/extra-courses/hostess-standards-4-0.jpg","assets/extra-courses/hostess-standards-4-1.jpg"],"links":[],"id":"101473"},{"title":"Работа с таблицей бронирования","text":"✅ Основные правила\nВ таблице бронирования хранится вся информация о забронированных столах.\nТаблицы бронирования доступны по ссылке. \nВ шапке каждого дня можно найти дату, тематику вечеринки и краткие условия, актуальные акции.\n\nВАЖНО:\n\nВносит информацию в таблицу бронирования тот, кто ее принял: хостес, менеджер, оператор КЦ или управляющий. \nТолько внесение предоплаты является подтверждением брони. \nПО на пакеты должна быть 100%, на депозиты в декабре и январе, корпоративы- минимум 50%.\nПолное закрытие зала бронирует только управляющий.\n🟣 ЦВЕТА:\nЗелёный цвет обозначает, что столы свободны.\nЖелтый - на предброни, столы без предоплаты.\nКрасным обозначаем брони, где есть предоплата либо когда гости уже за столом.\n❗Условные обозначения\nПервый столбец (А) каждого дня указывает на НОМЕР СТОЛА в заведении. \nВторой (В) - вместимость стола.\nТретий столбец (C) – минимальный депозит за стол.\nСтолбец (D)- количество гостей по факту.\nСтолбец (E) - ПОВОД события или типа отдыха гостей (Корпоратив/Девичник/День рождения и тд.).\nСтолбец (F) СТАРТ - указывает на время прихода гостей.\nСтолбец (G) - тот, кто продал, указывает фамилию менеджера общающегося с гостем при бронировании. Если хостес продает столик - то в данный столбец она пишет свою фамилию и (напр. Иванова).\nСтолбец (H) ФИО ЗАКАЗЧИКА указывает на имя гостя, который бронировал данный стол.\nСтолбец (I) - номер телефона гостя (вводится без “+” и “-” через 7, в формате 7XXX…)\nСтолбец (J) - примечания и пожелания несет в себе любые комментарии гостей, время (напр. фотограф и тд.), скидки гостей (напр. Кальян в подарок, скидка 10% торт свой и др.) FC, DC ,билеты\nСтолбец (K) оплата заполняется тем, кто ее принял! Информация должна нести в себе следующее: Сумма внесенной предоплаты, дата внесения и способ оплаты\nСтолбец (L) Предзаказы гостей/ Пакеты/когда приедут делать: заполняется ХОСТЕС. Она выделяет желтым, если предзаказ согласовывается с гостем, после согласования заливает красным, печатает, отдает на кухню и копию отправляет в чат Предзаказы.\nСтолбец (М) указывает билеты и способ их оплаты.\n❌ Отмена бронирования\nПод серым цветом в конце КАЖДОГО ДНЯ есть строчка ОТМЕНА.\nМы никогда не удаляем брони, гостей которые не пришли к нам.\nДанные брони мы переносим под строчку ОТМЕНА.","images":[],"links":[],"id":"101618"},{"title":"Телефонный этикет","text":"Добро пожаловать на седьмой урок нашего курса! Сегодня мы обсудим важность телефонного этикета и как правильно обрабатывать звонки от гостей. Телефонный этикет – это ключевая часть работы хостес, так как первый контакт гостей с рестораном часто происходит именно по телефону. Умение вежливо и профессионально общаться по телефону может значительно улучшить впечатление гостей и повысить лояльность к вашему ресторану.\n\nОсновные правила телефонного этикета\n\n1. Приветствие и представление:\n\nПри ответе на звонок важно вежливо поприветствовать гостя и представиться. Например: «Добрый день, \"Бар 90-е\". Меня зовут Анна, чем могу помочь?»\n\n2. Внимательность:\n\nВнимательно слушайте гостя и старайтесь понять его запросы. Не перебивайте и задавайте уточняющие вопросы, если что-то непонятно. Это поможет вам лучше понять потребности гостя и предложить ему наилучшее решение.\n\n3. Четкость и ясность:\n\nГоворите четко и внятно, избегая использования жаргона или сложных терминов. Убедитесь, что гость правильно понимает информацию, которую вы предоставляете. Если нужно, повторите ключевые моменты.\n\n4. Запись информации:\n\nЕсли гость делает бронирование или у него есть специальные запросы, обязательно записывайте всю информацию. Это поможет избежать ошибок и обеспечить точное выполнение пожеланий гостя.\n\n5. Вежливость и профессионализм:\n\nВсегда оставайтесь вежливыми и профессиональными, даже если гость раздражен или недоволен. Ваша задача – помочь гостю и создать для него положительный опыт общения с рестораном.\n\nПри бронировании столов в ресторане по телефону фиксируйте:\nимя и фамилию гостя;\nдату и время бронирования с точностью до 15 минут;\nколичество гостей( нельзя использовать фразу “Вы будете один?”;\nномер телефона для оперативной связи;\nпредпочтения относительно части зала и расположения стола, такие как тихая зона или столик у окна;\nлюбые дополнительные пожелания, например, заказ торта к дню рождения, детский стул или вазы для цветов.\n Всегда повторяйте записанную информацию, чтобы избежать ошибок.\nЕсли гости хотят провести банкет или фуршет, необходимо связаться с менеджером. Менеджер несет ответственность за оформление заказа, получение оплаты и организацию мероприятия\nПрактика\n\nТеперь давайте попробуем применить полученные знания на практике. Представьте, что вам звонит гость, который хочет забронировать столик на 4 человек на пятницу вечер. Ваша задача – провести телефонный разговор, следуя всем правилам этикета.","images":["assets/extra-courses/hostess-standards-6-0.jpg"],"links":[],"id":"101472"},{"title":"Рассадка гостей","text":"Добро пожаловать на восьмой урок нашего курса! Сегодня мы поговорим о том, как правильно организовать рассадку гостей. Рассадка гостей – это не просто процесс размещения их за столиками, это целое искусство, требующее учета множества факторов для создания комфортной и приятной атмосферы.\n\nВажно постоянно контролировать зал на наличие свободных мест, чтобы заранее знать, куда посадить следующих посетителей\n\nХостес должна рассаживать группы гостей равномерно по позициям официантов, так, чтобы на каждой позиции было одинаковое количество столов и гостей. Иными словами, одну группу гостей сажают на позицию одного официанта, другую – на позицию другого официанта, и такой порядок сохраняется, пока у всех официантов не будет занято хотя бы по одному столу.\n\nПожелания и предпочтения гостей должны превалировать над очередностью рассадки по каждой позиции, но хостес должна стараться рассаживать гостей равномерно\n\nВ моменты максимальной активности нужно отмечать на плане зала номера готовых столов. Гости с предварительным бронированием всегда имеют приоритет перед гостями из «живой» очереди.\nПринципы и правила рассадки гостей:\nРодители с детьми предпочитают столики в тихой части зала, где движение менее интенсивное, возможно потребуются специальные детские стулья.\nГости, пришедшие в одиночестве, предпочитают уютные столики у стены.\nПары предпочитают уединение.\nГостям с проблемами передвижения лучше предложить столики у входа и избегать заставлять их подниматься и спускаться по лестницам.\nПожилым людям комфортнее располагаться в тихой и легкодоступной части зала.\nЛюдей с ограниченными возможностями следует садить как можно быстрее, в стороне от проходов с интенсивным движением, при использовании инвалидных кресел, хостес должна убрать лишние стулья.\nБольшие группы гостей (более шести человек), пришедшие без предварительного бронирования, могут садиться за один большой стол или предлагается несколько маленьких столов.\nГостям, проводящим деловые встречи, вероятно, потребуется большой стол в менее оживленной части зала.\nИностранных гостей лучше посадить за стол, а затем, при необходимости, хостес может найти сотрудника для помощи с переводом на иностранный язык.\n\nЕсли в зале нет свободных столов, попросите гостей присесть за любой доступный стол и сообщите им о времени ожидания. Пересадку гостей следует осуществлять только при участии хостес. При приходе большой группы гостей попросите официантов создать общий стол из нескольких. Если образовалась очередь, приветствуйте всех гостей как вербально, так и невербально. Если нет свободных мест, вежливо попросите гостей подождать, указав реальное время ожидания. В листе ожидания фиксируйте информацию о гостях: их имя, телефон, количество и время прихода. Сообщите гостям, когда стол освободится, и рассаживайте их по очереди, как только они приходят. Не оставляйте своё рабочее место молча; дайте ожидающим гостям понять, что вы скоро вернетесь.","images":["assets/extra-courses/hostess-standards-7-0.jpg","assets/extra-courses/hostess-standards-7-1.jpg"],"links":[],"id":"101471"},{"title":"Управление выручкой ресторана","text":"Хостес, будучи первой точкой контакта для гостей, может существенно повлиять на их опыт и, следовательно, на их желание вернуться в ресторан. Хорошее приветствие и качественное обслуживание могут увеличить лояльность гостей и способствовать росту числа постоянных клиентов. Также хостес может способствовать увеличению среднего чека через грамотное управление бронированием и рассадкой.\n\nМетоды увеличения среднего чека\n\nОдним из ключевых аспектов работы хостес является умение предлагать гостям лучшие места и услуги, что может увеличить средний чек. Например, хостес может предложить гостям столики с лучшим видом, которые обычно стоят дороже. Также важно учитывать мероприятия и специальные предложения ресторана, такие как дегустационные ужины или винные пары.\n\nУправление бронированием и рассадкой\n\nЭффективное управление бронированием и рассадкой позволяет оптимизировать заполняемость ресторана и минимизировать время ожидания гостей. Хостес должна уметь грамотно распределять столики, чтобы обеспечить максимальную загрузку без ущерба для качества обслуживания. Это включает в себя учет предпочтений гостей, времени бронирования и текущей загрузки зала.","images":["assets/extra-courses/hostess-standards-8-0.jpg"],"links":[],"id":"101474"}],"outline":[{"type":"lesson","title":"Кто такая хостес?","lessonIndex":0},{"type":"lesson","title":"Внешний вид хостес","lessonIndex":1},{"type":"lesson","title":"Работа хостес на смене","lessonIndex":2},{"type":"lesson","title":"Скрипт общения хостес \"Бара 90-е\"","lessonIndex":3},{"type":"lesson","title":"Работа со сложными гостями","lessonIndex":4},{"type":"lesson","title":"Работа с таблицей бронирования","lessonIndex":5},{"type":"test","title":"Тест. Стандарты работы хостес"},{"type":"lesson","title":"Телефонный этикет","lessonIndex":6},{"type":"lesson","title":"Рассадка гостей","lessonIndex":7},{"type":"test","title":"Практическое задание по рассадке гостей"},{"type":"lesson","title":"Управление выручкой ресторана","lessonIndex":8},{"type":"test","title":"Тестирование"}],"testIds":["94441","104548","104557"]}'::jsonb,true,null,null) on conflict(id) do update set kind=excluded.kind,title=excluded.title,course_id=excluded.course_id,payload=excluded.payload,published=excluded.published,restaurant_id=excluded.restaurant_id,department=excluded.department;
commit;
